postcheck:
set -eu
scratch=$(mktemp -d)
trap 'rm -rf "$scratch"' EXIT
printf '<Project Sdk="Microsoft.NET.Sdk"><PropertyGroup><OutputType>Exe</OutputType><TargetFramework>net10.0</TargetFramework></PropertyGroup><ItemGroup><ProjectReference Include="%s/src/Calculator.csproj" /></ItemGroup></Project>\n' "$PWD" > "$scratch/Oracle.csproj"
cat > "$scratch/Program.cs" <<'CS'
using System;
using Fixture;
if (Calculator.Clamp(-2, 0, 5) != 0 || Calculator.Clamp(9, 0, 5) != 5 || Calculator.Clamp(2, 0, 5) != 2) Environment.Exit(1);
CS
dotnet run --project "$scratch/Oracle.csproj"

base_files.test/math.test.js:
import test from 'node:test';
import assert from 'node:assert/strict';
import { add, divide } from '../src/math.js';
test('adds',()=>assert.equal(add(2,3),5));
test('divides',()=>assert.equal(divide(6,2),3));

postcheck:
set -eu
rustc --test --edition=2021 -o .eval-check - <<'RS'
#[path = "src/lib.rs"] mod calc;
#[test] fn contract() { assert_eq!(calc::total(&[2,3,5]),10); assert_eq!(calc::total(&[]),0); assert_eq!(calc::total(&[-4,1]),-3); }
RS
./.eval-check
